float b2f(bool b) {return b ? 1.0 : 0.0;}

vec4 wave(vec2 fragTexCoord, float freq, float amp, float offset, float speed, float thickness, vec4 outline, vec4 col, vec4 bg) {
    float line = sin((fragTexCoord.x) * freq + iTime * speed) * amp + offset;
    vec2 line_uv = fragTexCoord - vec2(0.0, line);
    line_uv.x = 0.0;
    float line_mask = b2f(distance(line_uv, vec2(0.0)) < thickness);
    float inside_mask = b2f(distance(line_uv, vec2(0.0)) < thickness * 0.7);
    vec4 outp = bg;

    float gradient = fragTexCoord.y + offset;
    outp = mix(outp, outline, line_mask);
    outp = mix(outp, col * gradient, inside_mask);
    return outp;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    fragColor = vec4(0.1, 0.0, 0.4, 1.0);
    fragColor = wave(uv, 13.0, 0.05, 0.7, 0.7, 0.08, vec4(0.0, 0.0, 0.0, 1.0), vec4(0.0, 0.2, 0.8, 1.0), fragColor);
    fragColor = wave(uv, 10.0, 0.1, 0.6, 1.0, 0.09, vec4(0.0, 0.0, 0.0, 1.0), vec4(0.2, 0.4, 1.0, 1.0), fragColor);
    fragColor = wave(uv, 6.0, 0.125, 0.5, 1.0, 0.1, vec4(0.0, 0.0, 0.0, 1.0), vec4(0.5, 0.8, 1.0, 1.0), fragColor);
    fragColor = wave(uv, 3.0, 0.15, 0.4, 1.5, 0.12, vec4(0.0, 0.0, 0.0, 1.0), vec4(0.5, 1.0, 0.8, 1.0), fragColor);
}
